contract InvMutTest {
    C c;
    bool revertOnReceive;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(a <= address(this).balance);
        uint bal0 = address(c).balance;
        uint test0 = address(this).balance;
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        bool reverted;
        if (revertOnReceive) { revertOnReceive = false; revertOnReceive = false; }
        revertOnReceive = true;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        revertOnReceive = false;
        assert(
            reverted
                ? (address(c).balance == bal0 + a)
                : (address(this).balance == test0 && address(c).balance == bal0)
        );
    }
    receive() external payable {
        if (revertOnReceive) { revert(); }
    }
}

