// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;
    bool revertOnReceive;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(a <= address(this).balance);
        uint bal0 = address(c).balance;
        uint test0 = address(this).balance;
        try c.deposit{value: a}() {} catch { return; }
        bool reverted;
        if (revertOnReceive) { revertOnReceive = false; revertOnReceive = false; }
        revertOnReceive = true;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        revertOnReceive = false;
        assertTrue(reverted
                ? (address(c).balance == bal0 + a)
                : (address(this).balance == test0 && address(c).balance == bal0));
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {
        if (revertOnReceive) { revert(); }
    }
}
